const center = paddle.x + paddle.width / 2;
const hitPos = (ball.x - center) / (paddle.width / 2);  // -1 to +1

const angle = hitPos * (60 * Math.PI / 180);  // -60° to +60° in radians
const speed = Math.hypot(ball.ballSpeedX, ball.ballSpeedY);

ball.ballSpeedX = speed * Math.sin(angle);
ball.ballSpeedY = -Math.abs(speed * Math.cos(angle));  // always upward
